	// ...
	engine, err := filter.DefaultEngine()
	// ...
	switch s.Profile.Driver {
	case "mysql":
		dialect = filter.DialectMySQL
	case "postgres":
		dialect = filter.DialectPostgres
	default:
		dialect = filter.DialectSQLite
	}
	if _, err := engine.CompileToStatement(ctx, filterStr, filter.RenderOptions{Dialect: dialect}); err != nil {
```

**Store layer** — each dialect’s `memo.go` calls the same helper with its dialect:

- `store/db/sqlite/memo.go` → `filter.DialectSQLite`
- `store/db/mysql/memo.go` → `filter.DialectMySQL`
- `store/db/postgres/memo.go` → `filter.DialectPostgres`

```54:60:store/db/sqlite/memo.go
